<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_kuaibao_jd_com_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-kuaibao-jd-com-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $items = json_decode($item, true); if ($items) { $item = array(); foreach ($items as $it) { switch ($it['type']) { case 1: $item[] = '<p>' . $it['content'] . '</p>'; break; case 3: $item[] = '<h2>'.$it['content']['title'].'</h2>'; $item[] = '<p><img src="https://m.360buyimg.com/' . $it['content']['img'] . '"></p>'; break; } } $item = implode('', $item); } return $item; } } new qqworld_collector_parse_kuaibao_jd_com_post_content; ?>